fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // Since the input is non‐empty, we can safely take the first element
    let mut iter = x.into_iter();
    let first = iter.next().unwrap();
    let (mut min_val, mut max_val) = (first, first);

    // Iterate through the rest, updating min and max
    for v in iter {
        if v < min_val {
            min_val = v;
        }
        if v > max_val {
            max_val = v;
        }
    }

    // Return a two‐element Vec: [min, max]
    vec![min_val, max_val]
}

